def to_jsonable(value: Any) -> Any:
    """Convert request bodies to JSON-compatible values. Pydantic models are
    dumped with `model_dump(by_alias=True, exclude_none=True, mode="json")`."""
    dump = getattr(value, "model_dump", None)
    if callable(dump):
        return dump(by_alias=True, exclude_none=True, mode="json")
    if isinstance(value, enum.Enum):
        return value.value
    if isinstance(value, Mapping):
        return {str(k): to_jsonable(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set, frozenset)):
        return [to_jsonable(v) for v in value]
    return value


def _query_value(value: Any) -> str:
    value = to_jsonable(value)
    if isinstance(value, (datetime.datetime, datetime.date)):
        return value.isoformat()
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def build_query(params: Mapping[str, Any] | None) -> list[tuple[str, str | int | float | bool | None]]:
    """Query pairs; None values are dropped and lists repeat the key."""
    pairs: list[tuple[str, str | int | float | bool | None]] = []
    for key, value in (params or {}).items():
        if value is None:
            continue
        if isinstance(value, (list, tuple, set, frozenset)):
            pairs.extend((key, _query_value(v)) for v in value if v is not None)
        else:
            pairs.append((key, _query_value(value)))
    return pairs


def read_body(response: httpx.Response) -> Any:
    """Parsed body: None for 204 / empty, JSON for JSON content types, else text."""
    if response.status_code == 204 or not response.content:
        return None
    content_type = (response.headers.get("content-type") or "").lower()
    if "application/json" in content_type or "+json" in content_type:
        try:
            return response.json()
        except ValueError:
            return response.text
    return response.text


def _is_invalid_token(response: httpx.Response) -> bool:
    if response.status_code != 401:
        return False
    body = read_body(response)
    return isinstance(body, dict) and body.get("error") == "invalid_token"


